type Ledger struct {
	debit  atomic.Int64
	credit atomic.Int64
}

// invariant: debit == credit when no transfer is in progress
func (l *Ledger) Transfer() {
	l.debit.Add(1)
	l.credit.Add(1)
}

func (l *Ledger) Balanced() bool {
	d := l.debit.Load()
	c := l.credit.Load()
	return d == c
}
